INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('food', 'life', '«بِسْمِ اللَّهِ»، فَإِنْ نَسِيَ فِي أَوَّلِهِ قَالَ: «بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ»', 'In de Naam van Allaah — en wie het aan het begin vergeet, zegt: In de Naam van Allaah, aan het begin en aan het einde ervan.', 'In the Name of Allaah — and whoever forgets at the start says: In the Name of Allaah, at its beginning and its end.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التسمية قبل الطعام', 'toestand', 'state/situation', 1, 161),('food', 'life', '«بِسْمِ اللَّهِ»، وَيَأْكُلُ بِيَمِينِهِ مِمَّا يَلِيهِ', 'In de Naam van Allaah — en eet met je rechterhand en van wat vóór je ligt.', 'In the Name of Allaah — and eat with your right hand and from what is in front of you.', 'يجمع الآكل الثلاث، ولا يأكل بشماله؛ فعن ابن عمر مرفوعا: «لا يأكلن أحد منكم بشماله ولا يشربن بها؛ فإن الشيطان يأكل بشماله ويشرب بها» [مسلم (2020)].', 'De eter combineert de drie en eet niet met zijn linkerhand; want van Ibn 3umar is overgeleverd: ''Laat niemand van jullie met zijn linkerhand eten of drinken, want de shaytaan eet en drinkt met zijn linker''.', 'The eater combines the three and does not eat with the left hand; for it is transmitted from Ibn 3umar: ''Let none of you eat or drink with his left hand, for Satan eats and drinks with his left''.', 'لم يرد فيه أجر مخصوص، وقول عمر: «فما زالت تلك طعمتي بعد» شاهد أثر التربية النبوية.', 'Er is geen specifieke beloning voor overgeleverd, en 3umars woord ''zo bleef dat mijn manier van eten'' getuigt van de werking van de profetische opvoeding.', 'No specific reward is reported, and 3umar''s words ''that remained my way of eating'' testify to the effect of the prophetic upbringing.', 'وهيئة الأكل: التسمية واليمين ومما يليه', 'toestand', 'state/situation', 1, 162),('food', 'life', 'يسمي، ويشرب بيمينه على ثلاثة أنفاس، يُبين الإناء عن فيه في كل نفَس', 'Men zegt bismi-llaah, drinkt met de rechterhand in drie teugen en haalt daarbij telkens het drinkgerei van de mond weg.', 'One says bismi-llaah, drinks with the right hand in three breaths, removing the vessel from the mouth each time.', 'يحمد الله بين الأنفاس أو في آخرها، ولا يتنفس في داخل الإناء.', 'Men prijst Allaah tussen de teugen of aan het einde ervan, en ademt niet in het drinkgerei.', 'One praises Allaah between the sips or at the end, and does not breathe into the vessel.', 'العلة منصوصة: «أروى وأبرأ وأمرأ».', 'De reden is uitdrukkelijk: ''verzadigender, heilzamer en aangenamer''.', 'The reason is stated: ''more quenching, more wholesome and more agreeable''.', 'وهيئة الشرب: التنفس ثلاثا خارج الإناء', 'toestand', 'state/situation', 1, 163),('food', 'life', '«الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ»', 'Alle lof zij Allaah, Die mij dit te eten heeft gegeven en mij ervan heeft voorzien, zonder enige macht of kracht van mijn kant — dan worden de voorgaande zonden vergeven.', 'All praise is for Allaah who fed me this and provided it for me without any might or power on my part — then past sins are forgiven.', '', '', '', 'الأجر منصوص: «غُفر له ما تقدم من ذنبه».', 'De beloning is uitdrukkelijk: ''zijn voorgaande zonden worden hem vergeven''.', 'The reward is stated: ''his past sins are forgiven him''.', 'وإذا فرغ من طعامه قال', 'toestand', 'state/situation', 1, 164),('food', 'life', '«الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا»', 'Alle lof zij Allaah: een veelvuldige, goede en gezegende lof — een lof die niet toereikend kan zijn, die niet wordt beëindigd en waarvan men nooit onafhankelijk is, onze Heer.', 'Praise be to Allaah: abundant, good, blessed praise — never sufficient, never ended, never dispensed with, our Lord.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا رفع مائدته قال', 'toestand', 'state/situation', 1, 165),('food', 'life', '«اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ، وَارْحَمْهُمْ»', 'O Allaah, zegen hen in wat U hun heeft geschonken, vergeef hen en wees hen genadig.', 'O Allaah, bless them in what You have provided them, forgive them, and have mercy on them.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء الضيف لأهل الطعام', 'toestand', 'state/situation', 1, 166),('food', 'life', '«اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ»', 'O Allaah, zegen het voor ons en schenk ons er meer van (bij melk); en bij ander voedsel: O Allaah, zegen het voor ons en voed ons met iets beters.', 'O Allaah, bless it for us and give us more of it (for milk); and for other food: O Allaah, bless it for us and feed us with what is better.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'من سقاه الله لبنا فليقل', 'toestand', 'state/situation', 1, 167),('sneezing', 'life', '«الْحَمْدُ لِلَّهِ»، وَلْيَقُلْ لَهُ أَخُوهُ: «يَرْحَمُكَ اللَّهُ»، فَإِذَا قَالَ لَهُ: يَرْحَمُكَ اللَّهُ، فَلْيَقُلْ: «يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ»', '(De nieser:) Alle lof zij Allaah. (Zijn broeder:) Moge Allaah je genadig zijn. (De nieser:) Moge Allaah jullie leiden en jullie toestand verbeteren.', '(The sneezer:) All praise is for Allaah. (His brother:) May Allaah have mercy on you. (He replies:) May Allaah guide you and set your affairs in order.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند العطاس', 'toestand', 'state/situation', 1, 168),('sneezing', 'life', 'تَغْطِيَةُ الْوَجْهِ بِالْيَدِ أَوِ الثَّوْبِ، وَخَفْضُ الصَّوْتِ، مَعَ قَوْلِ: «الْحَمْدُ لِلَّهِ»', 'Men bedekt het gezicht met de hand of een kledingstuk en dempt het geluid bij het niezen, en zegt: al-hamdu li-llaah.', 'One covers the face with the hand or a garment and lowers the sound when sneezing, saying: al-hamdu li-llaah.', 'يضع يده أو ثوبه على فيه عند العطسة ويخفض صوته ثم يحمد الله.', 'Men legt de hand of het kledingstuk op de mond bij het niezen, dempt het geluid en prijst dan Allaah.', 'One places the hand or garment on the mouth when sneezing, lowers the sound, then praises Allaah.', 'لم يرد فيه أجر مخصوص، وفيه كف الأذى وحسن الأدب.', 'Er is geen specifieke beloning voor overgeleverd, daarin ligt het weren van schade en goede manieren.', 'No specific reward is reported, in it is warding off harm and good manners.', 'ومن هيئته ﷺ في العطاس', 'toestand', 'state/situation', 1, 169),('sneezing', 'life', '«يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ»', 'Moge Allaah jullie leiden en jullie toestand verbeteren.', 'May Allaah guide you and set your affairs in order.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا عطس الكافر فحمد الله قيل له', 'toestand', 'state/situation', 1, 170),('sneezing', 'life', 'فإذا تثاءب أحدكم فليرده ما استطاع، وليكظم', 'Men onderdrukt de geeuw zoveel mogelijk; er hoort geen dhikr-formule bij.', 'One suppresses the yawn as much as possible; no dhikr formula is prescribed.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التثاؤب من الشيطان', 'toestand', 'state/situation', 1, 171),('sneezing', 'life', 'يرد التثاؤب ما استطاع، فإن غلبه أمسك بيده على فيه، ولا ذكر فيه بلفظ', 'Men onderdrukt de geeuw; lukt dat niet, dan houdt men de hand op de mond. Er is geen vaste formule.', 'One suppresses the yawn; if unable, one places the hand over the mouth. No fixed wording.', 'يكظم أولا، فإن لم يندفع وضع يده على فمه، ولم يثبت قول شيء عند التثاؤب.', 'Men onderdrukt eerst; lukt dat niet, dan legt men de hand op de mond; er is geen uitspraak bij het geeuwen overgeleverd.', 'One suppresses first; if that fails, one places the hand on the mouth; no utterance upon yawning is transmitted.', 'العلة منصوصة: «فإن الشيطان يدخل».', 'De reden is uitdrukkelijk: ''want de shaytaan komt binnen''.', 'The reason is stated: ''for Satan enters''.', 'وهيئة دفع التثاؤب باليد', 'toestand', 'state/situation', 1, 172),('anger', 'state', '«أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ»', 'Ik zoek toevlucht bij Allaah tegen de vervloekte shaytaan — wie het bij woede zegt, van hem wijkt wat hij voelt.', 'I seek refuge in Allaah from the accursed devil — whoever says it in anger, what he feels departs from him.', '', '', '', 'الأجر منصوص: «لذهب عنه ما يجد».', 'De beloning is uitdrukkelijk: ''wat hij voelt zal van hem wijken''.', 'The reward is stated: ''what he feels will depart from him''.', 'عند الغضب', 'toestand', 'state/situation', 1, 173),('distress', 'state', '«لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ»', 'Er is geen god behalve Allaah, de Geweldige, de Verdraagzame. Er is geen god behalve Allaah, de Heer van de geweldige Troon. Er is geen god behalve Allaah, de Heer van de hemelen, de Heer van de aarde en de Heer van de edele Troon.', 'None has the right to be worshipped except Allaah, the Magnificent, the Forbearing. None has the right to be worshipped except Allaah, Lord of the Magnificent Throne. None has the right to be worshipped except Allaah, Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء الكرب', 'toestand', 'state/situation', 1, 174),('distress', 'state', '«اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ»', 'O Allaah, op Uw barmhartigheid hoop ik; laat mij dus zelfs geen oogwenk aan mijzelf over, en breng al mijn zaken in orde. Er is geen god behalve U.', 'O Allaah, for Your mercy I hope; so do not leave me to myself even for the blink of an eye, and set right all my affairs. None has the right to be worshipped except You.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند الهم', 'toestand', 'state/situation', 1, 175),('distress', 'state', '«اللَّهُ اللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا»', 'Allaah, Allaah is mijn Heer; ik ken Hem geen enkele deelgenoot toe.', 'Allaah, Allaah is my Lord; I associate nothing with Him.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ويقول عند الكرب', 'toestand', 'state/situation', 1, 176),('distress', 'state', '«لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ»', 'Er is geen god behalve U, verheven bent U; waarlijk, ik behoorde tot de onrechtplegers — geen moslim smeekt hiermee over iets of Allaah verhoort hem.', 'None has the right to be worshipped except You; glory be to You, indeed I was among the wrongdoers — no Muslim supplicates with it for anything except that Allaah answers him.', '', '', '', 'الأجر منصوص: ما دعا بها مسلم في شيء قط إلا استجاب الله له.', 'De beloning is uitdrukkelijk: geen moslim smeekt hiermee over iets of Allaah verhoort hem.', 'The reward is stated: no Muslim supplicates with it for anything but Allaah answers him.', 'دعوة ذي النون', 'toestand', 'state/situation', 1, 177),('distress', 'state', '«اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ: أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي»', 'O Allaah, ik ben Uw dienaar, zoon van Uw dienaar, zoon van Uw dienares. Mijn voorhoofdslok is in Uw Hand, Uw oordeel over mij is gaande en Uw beschikking over mij is rechtvaardig. Ik vraag U bij elke Naam die U toebehoort, waarmee U Uzelf heeft genoemd, of die U in Uw Boek heeft neergezonden, of die U aan één van Uw schepselen heeft onderwezen, of die U in de kennis van het verborgene bij U heeft gehouden: maak de Koran de lente van mijn hart, het licht van mijn borst, het verdrijven van mijn verdriet en het verdwijnen van mijn zorgen.', 'O Allaah, I am Your slave, son of Your slave, son of Your maidservant. My forelock is in Your Hand; Your judgement over me is ever executed and Your decree concerning me is just. I ask You by every Name that is Yours, by which You named Yourself, or revealed in Your Book, or taught to any of Your creation, or kept with Yourself in the knowledge of the unseen: make the Qur''an the spring of my heart, the light of my chest, the removal of my sadness and the departure of my anxiety.', '', '', '', 'الأجر منصوص: يذهب الله همه وحزنه ويبدله مكانه فرحا.', 'De beloning is uitdrukkelijk: Allaah verdrijft zijn zorg en verdriet en vervangt het door vreugde.', 'The reward is stated: Allaah removes his worry and grief and replaces it with joy.', 'دعاء الهم والحزن', 'toestand', 'state/situation', 1, 178),('distress', 'state', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ»', 'O Allaah, ik zoek toevlucht bij U tegen zorgen en verdriet, tegen onvermogen en luiheid, tegen gierigheid en lafheid, en tegen de last van schulden en de overheersing door mensen.', 'O Allaah, I seek refuge in You from worry and grief, from incapacity and laziness, from miserliness and cowardice, and from the burden of debt and the domination of men.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وكان ﷺ يكثر أن يقول', 'toestand', 'state/situation', 1, 179),('debt', 'state', '«اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ»', 'O Allaah, maak het toegestane voor mij toereikend zodat ik het verbodene niet nodig heb, en maak mij door Uw gunst onafhankelijk van iedereen buiten U.', 'O Allaah, suffice me with what You have made lawful so I need not the unlawful, and enrich me by Your bounty so I depend on none besides You.', '', '', '', 'الأجر منصوص: لو كان عليه مثل الجبل دينا أداه الله عنه.', 'De beloning is uitdrukkelijk: al had hij een schuld als een berg, Allaah zou die voor hem aflossen.', 'The reward is stated: even were his debt like a mountain, Allaah would settle it for him.', 'دعاء قضاء الدين', 'toestand', 'state/situation', 1, 180);